import { Roadmap } from "march/landing"
import { Button } from "march/ui"

// pizza takibi: her basışta sipariş bir adım ilerler; geçen adımlar biter, sıradaki yanıp söner
const STEPS = [
  { title: "Sipariş alındı", body: "Margarita, bol peynir 🧀" },
  { title: "Fırında", body: "Taş fırın, 3 dakika 🔥" },
  { title: "Yolda", body: "Kurye köşeyi döndü 🛵" },
  { title: "Afiyet olsun", body: "Kapıdayız 🍕" },
]

export function PizzaTracker() {
  let $stage = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Button on:click={() => $stage = $stage >= STEPS.length - 1 ? 0 : $stage + 1}>{$stage >= STEPS.length - 1 ? "Yeni sipariş" : "Sonraki adım"}</Button>
    {() => {
      const stage = $stage
      return <Roadmap scroll={false} labels={{ done: "Tamam", now: "Şimdi", next: "Bekliyor" }}
        items={STEPS.map((s, i) => ({ ...s, status: (i < stage ? "done" : i === stage ? "now" : "next") as "done" | "now" | "next" }))} />
    }}
  </div>
}

import { Roadmap } from "march/landing"

// bir not uygulamasının yol haritası: sayfa kaydıkça çizgi dolar, geçilen noktalar yanar
export function ProductRoadmap() {
  return <Roadmap labels={{ done: "Yayında", now: "Yapılıyor", next: "Planlandı" }} items={[
    { time: "Ocak 2026", title: "Çevrimdışı notlar", body: "İnternet yokken yaz, gelince eşitlensin.", status: "done" },
    { time: "Nisan 2026", title: "Paylaşılan defterler", body: "Ailen ya da ekibinle aynı defterde.", status: "done" },
    { time: "Eylül 2026", title: "Sesli not → yazı", body: "Konuş, Türkçe metne dönsün.", status: "now" },
    { time: "2027", title: "El yazısı tanıma", body: "Tablette kalemle yaz, aranabilir olsun.", status: "next" },
    { time: "2027", title: "Masaüstü uygulaması", body: "Windows ve macOS için.", status: "next" },
  ]} />
}

import { Roadmap } from "march/landing"
import { Card, Segmented, Toggle } from "march/ui"
import { flag, sparkles, star } from "march/icons"

// Roadmap'in bütün özellikleri bir arada: girdiler (time, title, body, status, icon), rozetler (badges: açık, kendi
// rozetin ya da yok), kaydırdıkça dolma (scroll), çizgi (rail), durum metinleri (labels), giriş (reveal) ve sınıf (class)
type RoadmapStatus = "done" | "now" | "next"
const EMOJI: Record<RoadmapStatus, string> = { done: "✅", now: "⏳", next: "🗓️" }

export function RoadmapLab() {
  let $badges: string = "on"
  let $rail = true
  let $scroll = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Rozetler" options={[{ value: "on", label: "rozet" }, { value: "own", label: "kendi rozetim" }, { value: "off", label: "rozetsiz" }]} bind:value={$badges} />
        <Toggle label="Çizgi" bind:value={$rail} />
        <Toggle label="Kaydırdıkça dolsun" bind:value={$scroll} />
      </div>
    </Card>
    {() => {
      // bu satırda okunan durumlar değişince yol haritası yeniden çizilir
      const badges = $badges, rail = $rail, scroll = $scroll
      return <Roadmap class="lab-rm" rail={rail} scroll={scroll} reveal={false}
        badges={badges === "off" ? false : badges === "own" ? (s: RoadmapStatus, text: unknown) => <span class="lab-badge">{EMOJI[s]} {text}</span> : true}
        labels={{ done: "Yayında", now: "Yapılıyor", next: "Sırada" }}
        items={[
          { time: "Bahar", title: "Tanışma yemekleri", body: "Aynı masada yeni insanlar.", status: "done", icon: flag },
          { time: "Yaz", title: "Bilet satışı", body: "Kontenjan ve ödeme tek yerde.", status: "done" },
          { time: "Sonbahar", title: "Yeni şehirler", body: "Her ilde etkinlik.", status: "now", icon: sparkles },
          { time: "Kış", title: "Topluluk ödülleri", status: "next", icon: star },
        ]} />
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { RoadmapLab } from "./RoadmapLab.tsx"

// RoadmapLab'in testleri: kaydedince Testler sekmesinde çalışır
test("dört girdi; durum rozetleri kendi metinleriyle", () => {
  const s = renderTest(() => <RoadmapLab />)
  expect(s.all(".lab-rm .m-rm-tl > li").length).toBe(4)
  const badges = s.all(".lab-rm .m-rm-badge").map((b: Element) => b.textContent)
  expect(badges).toEqual(["Yayında", "Yayında", "Yapılıyor", "Sırada"])
})

test("kaydırma kapalıyken çizgi dolu; çizgi kapanınca gider", async () => {
  const s = renderTest(() => <RoadmapLab />)
  expect(s.get(".lab-rm")?.classList.contains("is-scroll")).toBe(false)
  expect(s.get(".lab-rm .m-rm-rail")).not.toBe(null)
  await s.click("Çizgi")
  expect(s.get(".lab-rm .m-rm-rail")).toBe(null)
})

test("kendi rozetim: durum ve metin bir arada", async () => {
  const s = renderTest(() => <RoadmapLab />)
  await s.click("kendi rozetim")
  expect(s.get(".lab-rm .m-rm-badge")).toBe(null)
  expect(s.get(".lab-rm .lab-badge")?.textContent).toContain("Yayında")
})

test("rozetsiz: başlıklar yalın", async () => {
  const s = renderTest(() => <RoadmapLab />)
  await s.click("rozetsiz")
  expect(s.get(".lab-rm .m-rm-badge")).toBe(null)
  expect(s.get(".lab-rm .lab-badge")).toBe(null)
  expect(s.sees("Topluluk ödülleri")).toBe(true)
})
